            <polyline points={"113.0,110.0 113.1,107.2 113.6,104.4 114.3,101.7 115.3,99.0 116.6,96.5 118.2,94.1 119.9,91.9 121.9,89.9 124.1,88.2 126.5,86.6"} fill={"none"} stroke={"#16a34a"} strokeWidth={"2.5"}></polyline>
