          <b className={"font-bold text-slate-900"}>
            {<MathText>{"duas retas transversais"}</MathText>}
          </b>
          {<MathText>{" determina nelas "}</MathText>}
          <b className={"font-bold text-slate-900"}>
            {<MathText>{"segmentos proporcionais"}</MathText>}
          </b>
          {<MathText>{"."}</MathText>}
