          {<MathText>{"\\[ \\dfrac{AB}{BC} = \\dfrac{DE}{EF} \\qquad\\text{ou}\\qquad \\dfrac{AB}{DE} = \\dfrac{BC}{EF} \\]"}</MathText>}
