          <b className={"font-bold text-slate-900"}>
            {<MathText>{"pelo caminho mais curto"}</MathText>}
          </b>
          {<MathText>{". Esse caminho é um segmento que sai de A e encontra BC fazendo "}</MathText>}
          <b className={"font-bold text-slate-900"}>
            {<MathText>{"ângulo reto"}</MathText>}
          </b>
          {<MathText>{". Ele se chama "}</MathText>}
          <b className={"font-bold text-slate-900"}>
            {<MathText>{"altura relativa à hipotenusa"}</MathText>}
          </b>
          {<MathText>{". Chamamos de "}</MathText>}
          <b className={"font-bold text-slate-900"}>
            {<MathText>{"H"}</MathText>}
          </b>
          {<MathText>{" o ponto onde ela encontra BC e de \\(h = AH\\) o seu comprimento."}</MathText>}
