            {<MathText>{"Os três triângulos na mesma posição: ângulo reto embaixo à esquerda, β embaixo à direita, γ em cima. Cateto horizontal (amarelo), vertical (verde) e hipotenusa (rosa) se correspondem."}</MathText>}
