        <h3 className={"mt-7 text-lg font-extrabold text-indigo-800"}>
          {<MathText>{"6.1 Primeira relação: \\(c^2 = a \\cdot m\\)"}</MathText>}
        </h3>
        {<MathText>{" "}</MathText>}
        <p className={"mt-3 leading-7 text-slate-600"}>
          {<MathText>{"Compare △ ABC com △ HBA. Pela tabela: hipotenusa \\(a \\leftrightarrow c\\), cateto horizontal \\(c \\leftrightarrow m\\), cateto vertical \\(b \\leftrightarrow h\\). Então:"}</MathText>}
        </p>
        {<MathText>{" "}</MathText>}
        <div className={"mt-4 overflow-x-auto rounded-2xl border-2 border-indigo-300 bg-[#fffef9] p-5 text-center text-xl"}>
          {<MathText>{"\\[ \\dfrac{a}{c} = \\dfrac{c}{m} = \\dfrac{b}{h} \\]"}</MathText>}
        </div>
        {<MathText>{" "}</MathText>}
        <p className={"mt-3 leading-7 text-slate-600"}>
          {<MathText>{"Pegue a primeira igualdade e faça a multiplicação cruzada:"}</MathText>}
        </p>
        {<MathText>{" "}</MathText>}
        <div className={"bg-[#fffef9] bg-[linear-gradient(#e0e7ff_1px,transparent_1px)] bg-[length:100%_2rem] border border-indigo-200 shadow-sm rounded-xl p-5 mt-4"}>
          <div className={"font-serif text-lg italic leading-8 text-blue-900"}>
            {<MathText>{" "}</MathText>}
            <div>
              {<MathText>{"\\(\\dfrac{a}{c} = \\dfrac{c}{m}\\)"}</MathText>}
            </div>
            {<MathText>{" "}</MathText>}
            <div>
              {<MathText>{"\\(c \\cdot c = a \\cdot m\\)"}</MathText>}
            </div>
            {<MathText>{" "}</MathText>}
            <div>
              {<MathText>{"\\(\\boxed{c^2 = a \\cdot m}\\)"}</MathText>}
            </div>
            {<MathText>{" "}</MathText>}
          </div>
        </div>
        {<MathText>{" "}</MathText>}
        <p className={"mt-3 leading-7 text-slate-600"}>
          {<MathText>{"Pegue agora a primeira e a terceira razões: \\(\\dfrac{a}{c} = \\dfrac{b}{h}\\), cruzando: \\(a \\cdot h = b \\cdot c\\). É a "}</MathText>}
          <b className={"font-bold text-slate-900"}>
            {<MathText>{"quarta relação"}</MathText>}
          </b>
          {<MathText>{":"}</MathText>}
        </p>
        {<MathText>{" "}</MathText>}
        <div className={"mt-4 overflow-x-auto rounded-2xl border-2 border-indigo-300 bg-[#fffef9] p-5 text-center text-xl"}>
          {<MathText>{"\\[ a \\cdot h = b \\cdot c \\]"}</MathText>}
        </div>
        {<MathText>{" "}</MathText>}
        <h3 className={"mt-7 text-lg font-extrabold text-indigo-800"}>
          {<MathText>{"6.2 Segunda relação: \\(b^2 = a \\cdot n\\)"}</MathText>}
        </h3>
        {<MathText>{" "}</MathText>}
        <p className={"mt-3 leading-7 text-slate-600"}>
          {<MathText>{"Compare △ ABC com △ HAC: hipotenusa \\(a \\leftrightarrow b\\), cateto horizontal \\(c \\leftrightarrow h\\), cateto vertical \\(b \\leftrightarrow n\\)."}</MathText>}
        </p>
        {<MathText>{" "}</MathText>}
        <div className={"bg-[#fffef9] bg-[linear-gradient(#e0e7ff_1px,transparent_1px)] bg-[length:100%_2rem] border border-indigo-200 shadow-sm rounded-xl p-5 mt-4"}>
          <div className={"font-serif text-lg italic leading-8 text-blue-900"}>
            {<MathText>{" "}</MathText>}
            <div>
              {<MathText>{"\\(\\dfrac{a}{b} = \\dfrac{c}{h} = \\dfrac{b}{n}\\)"}</MathText>}
            </div>
            {<MathText>{" "}</MathText>}
            <div>
              {<MathText>{"Tomando \\(\\dfrac{a}{b} = \\dfrac{b}{n}\\): \\(b \\cdot b = a \\cdot n\\)"}</MathText>}
            </div>
            {<MathText>{" "}</MathText>}
            <div>
              {<MathText>{"\\(\\boxed{b^2 = a \\cdot n}\\)"}</MathText>}
            </div>
            {<MathText>{" "}</MathText>}
          </div>
        </div>
        {<MathText>{" "}</MathText>}
        <h3 className={"mt-7 text-lg font-extrabold text-indigo-800"}>
          {<MathText>{"6.3 Terceira relação: \\(h^2 = m \\cdot n\\)"}</MathText>}
        </h3>
        {<MathText>{" "}</MathText>}
        <p className={"mt-3 leading-7 text-slate-600"}>
          {<MathText>{"Compare agora os dois triângulos pequenos, △ HBA e △ HAC: hipotenusa \\(c \\leftrightarrow b\\), cateto horizontal \\(m \\leftrightarrow h\\), cateto vertical \\(h \\leftrightarrow n\\)."}</MathText>}
        </p>
        {<MathText>{" "}</MathText>}
        <div className={"bg-[#fffef9] bg-[linear-gradient(#e0e7ff_1px,transparent_1px)] bg-[length:100%_2rem] border border-indigo-200 shadow-sm rounded-xl p-5 mt-4"}>
          <div className={"font-serif text-lg italic leading-8 text-blue-900"}>
            {<MathText>{" "}</MathText>}
            <div>
              {<MathText>{"\\(\\dfrac{c}{b} = \\dfrac{m}{h} = \\dfrac{h}{n}\\)"}</MathText>}
            </div>
            {<MathText>{" "}</MathText>}
            <div>
              {<MathText>{"Tomando \\(\\dfrac{m}{h} = \\dfrac{h}{n}\\): \\(h \\cdot h = m \\cdot n\\)"}</MathText>}
            </div>
            {<MathText>{" "}</MathText>}
            <div>
              {<MathText>{"\\(\\boxed{h^2 = m \\cdot n}\\)"}</MathText>}
            </div>
            {<MathText>{" "}</MathText>}
          </div>
        </div>
        {<MathText>{" "}</MathText>}
        <h3 className={"mt-7 text-lg font-extrabold text-indigo-800"}>
          {<MathText>{"6.4 As relações métricas: quadro-resumo"}</MathText>}
        </h3>
        {<MathText>{" "}</MathText>}
        <div className={"mt-4 overflow-x-auto rounded-2xl border-2 border-indigo-300 bg-[#fffef9] p-5 text-center text-xl"}>
          {<MathText>{"\\[ \\boxed{c^2 = a\\cdot m} \\qquad \\boxed{b^2 = a\\cdot n} \\qquad \\boxed{h^2 = m\\cdot n} \\qquad \\boxed{a\\cdot h = b\\cdot c} \\qquad \\boxed{a = m + n} \\]"}</MathText>}
        </div>
        {<MathText>{" "}</MathText>}
